def valid_date(date):
    if not date:
        return False

    month, day, year = date.split('-')
    month = int(month)
    day = int(day)
    year = int(year)

    if month < 1 or month > 12:
        return False

    if day < 1 or day > 31:
        return False

    if month == 2:
        if day > 29:
            return False

    if month == 1:
        if day > 1:
            return False

    if month == 2:
        if day > 28:
            return False

    if month == 4:
        if day > 30:
            return False

    return True
